INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 13, 'theory', 'Квиз: nftables и firewalld');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 0, 'Пакет принят правилом accept в базовой цепочке input таблицы inet filter (приоритет 0). В другой таблице есть цепочка input с приоритетом 10 и политикой drop, без подходящих правил. Что будет с пакетом?', '["Пакет принят: accept отменяет остальные цепочки", "Пакет принят, потому что политика drop действует только на forward", "Пакет отброшен политикой второй цепочки", "Пакет отброшен, потому что цепочка с приоритетом 10 выполняется раньше"]', 2, 'accept заканчивает только свою базовую цепочку; пакет идёт в цепочку того же хука с большим приоритетом, а там без правил работает политика drop. Порядок задаёт приоритет: ноль идёт раньше десяти.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 1, 'Пакет приходит на интерфейс eth0 (зона public) с адреса, который указан в sources зоны internal. Какая зона обработает пакет по умолчанию?', '["internal: источник проверяют раньше интерфейса", "public: интерфейс сильнее источника", "Зона по умолчанию, она не зависит от интерфейса", "Обе зоны по очереди"]', 0, 'firewalld сначала ищет зону по источнику, затем по интерфейсу и только потом берёт зону по умолчанию. Приоритет зоны в новых версиях может изменить порядок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 2, 'Вы загрузили цепочку input с политикой drop и единственным правилом на порт 22, без правила про ct state established. Ваша открытая сессия SSH идёт на порт 2222. Что будет?', '["Сессия продолжит работать: она уже установлена", "Пакеты сессии на порт 2222 отбросит политика, сессия зависнет", "Ядро пропускает сессию, пока не истечёт таймаут слежения", "Сессия сама переключится на порт 22"]', 1, 'Состояние соединения само ничего не разрешает: без правила ct state established,related accept пакеты сессии без собственного правила попадают под политику drop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 3, 'В каком хуке имеет смысл правило masquerade?', '["prerouting", "input", "forward", "postrouting"]', 3, 'Маскарад подставляет адрес выходного интерфейса, поэтому он допустим только в postrouting цепочки типа nat. Подмена адреса назначения делается в prerouting.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 4, 'Почему на гипервизоре с firewalld и libvirt не стоит выполнять nft flush ruleset?', '["Команда перезагружает ядро", "Она очищает только таблицу filter", "Она удаляет все таблицы, включая созданные firewalld и libvirt, и их правила пропадают до перезагрузки служб", "Она отключает модуль nf_tables навсегда"]', 2, 'По документации nft, flush ruleset удаляет все таблицы и всё содержимое. Правила firewalld и сети libvirt придётся восстанавливать перезагрузкой этих служб.');
